<?php $pay=$salary ?? [];$financeActive=(new \Tivoli\Service\FinanceService(access_service()))->installed();?>
<section class="card"><h2>Salary & payment details</h2><p class="muted">Restricted HR / finance information. Recording salary terms does not make a payment.</p><?php if(!$catalogue['momo']||(!$financeActive&&!$catalogue['bank'])):?><p class="notice">Add your approved payment providers in Settings before selecting them for salary payments.</p><?php endif?><form method="post" autocomplete="off" data-hr-salary><?php hr_fields('save_salary',$id,$version);?><input type="hidden" name="expected_salary_id" value="<?=(int)($pay['id'] ?? 0)?>"><div class="grid"><?php hr_input('Agreed basic salary (GHS)','amount',$pay['amount'] ?? '','text',true,'inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?"');hr_select('Pay frequency','frequency',['monthly'=>'Monthly','fortnightly'=>'Fortnightly','weekly'=>'Weekly','daily'=>'Daily'],$pay['frequency'] ?? 'monthly',true);hr_input('Effective from','effective_date',$pay['effective_date'] ?? gmdate('Y-m-d'),'date',true);hr_select('Preferred payment method','preferred',$financeActive?['momo'=>'Mobile money (MoMo)']:['momo'=>'Mobile money (MoMo)','bank'=>'Bank transfer','cash'=>'Cash'],$pay['preferred'] ?? 'momo',true);?></div>
<section class="hr-subsection"><h3>Mobile money details</h3><div class="grid"><?php hr_catalogue_select('MoMo provider','momo_id',$catalogue['momo'],$pay['momo_id'] ?? '');hr_input('Registered account name','momo_name',$pay['momo_name'] ?? '');?><label class="hr-field">MoMo number<span class="password"><input id="hr-momo-number" name="momo_number" type="password" value="<?=access_h($pay['momo_number'] ?? '')?>" inputmode="numeric" autocomplete="off"><button type="button" class="secondary" data-password-toggle="hr-momo-number" aria-pressed="false" aria-label="Show MoMo number">Show</button></span></label></div></section>
<?php if(!$financeActive):?><section class="hr-subsection"><h3>Bank account details</h3><div class="grid"><?php hr_catalogue_select('Bank name','bank_id',$catalogue['bank'],$pay['bank_id'] ?? '');hr_input('Branch','branch',$pay['branch'] ?? '');hr_input('Account holder name','bank_holder',$pay['bank_holder'] ?? '');?><label class="hr-field">Account number<span class="password"><input id="hr-bank-number" name="bank_number" type="password" value="<?=access_h($pay['bank_number'] ?? '')?>" inputmode="numeric" autocomplete="off"><button type="button" class="secondary" data-password-toggle="hr-bank-number" aria-pressed="false" aria-label="Show bank account number">Show</button></span></label><?php hr_select('Account type','account_type',['savings'=>'Savings','current'=>'Current','other'=>'Other'],$pay['account_type'] ?? 'savings');hr_input('Bank / routing code','routing_code',$pay['routing_code'] ?? '');?></div></section>
<?php else:?><input type="hidden" name="account_type" value="savings"><p>MoMo is required for new salary revisions. Existing historical bank details remain stored.</p><?php endif?><?php if($can('hr.settings')):?><p><a href="<?=access_h(access_url('hr-settings.php?section=payments'))?>">Manage Payment Providers in Settings</a></p><?php endif?><?php hr_textarea('Payment instructions / salary notes','notes',$pay['notes'] ?? '',false,1000);?><label class="hr-check"><input type="checkbox" name="confirmed" value="1" required> Payment details confirmed with the staff member *</label><?php hr_reason();?><p><button>Save salary revision</button></p></form>
<h3>Salary revision history</h3><p class="muted">Prior revisions remain stored. Effective dates distinguish changes; this page shows the latest recorded revision.</p><div class="scroll"><table><thead><tr><th>Revision</th><th>Effective from</th><th>Recorded</th><th>Actor</th></tr></thead><tbody><?php foreach(($pay['history'] ?? []) as $revision):?><tr><td>#<?=(int)$revision['id']?></td><td><?=access_h(display_date($revision['effective_date']))?></td><td><?=access_h(display_date($revision['created_at']))?> UTC</td><td>#<?=(int)$revision['created_by']?></td></tr><?php endforeach?></tbody></table></div></section>
